from pathlib import Path
import re
roots=[Path('README.md'),Path('AGENTS.md'),Path('docs'),Path('web/README.md')]
files=[]
for r in roots:
    if r.is_file(): files.append(r)
    elif r.exists(): files += list(r.rglob('*.md'))
pat=re.compile(r'(?<!!)\[[^\]]*\]\(([^)]+)\)')
broken=[]
for f in files:
    text=f.read_text(errors='replace')
    for n,line in enumerate(text.splitlines(),1):
        for m in pat.finditer(line):
            target=m.group(1).strip().split()[0].strip('<>')
            if target.startswith(('http://','https://','mailto:','#')): continue
            target=target.split('#',1)[0]
            if not target: continue
            p=(f.parent/target).resolve()
            if not p.exists(): broken.append((str(f),n,target))
print('=== BROKEN LOCAL MARKDOWN LINKS ===')
for x in broken: print(f'{x[0]}:{x[1]} -> {x[2]}')
print('BROKEN_COUNT',len(broken))
# inbound references among docs
docs=sorted(Path('docs').rglob('*.md'))
inbound={p:0 for p in docs}
for f in files:
    text=f.read_text(errors='replace')
    for p in docs:
        rel_names={p.name, str(p), str(p.relative_to('docs'))}
        if any(name in text for name in rel_names):
            if f.resolve()!=p.resolve(): inbound[p]+=1
print('=== DOCS WITH ZERO INBOUND MD REFERENCES ===')
for p,c in inbound.items():
    if c==0: print(p)
